 99	/**
100	 * Guards against path-traversal attacks on the project slug URL parameter.

101	 *
102	 * Rejects any slug that does not satisfy the safe-slug rules
103	 * (lowercase alphanumeric + hyphens, must start with an alphanumeric character).
104	 * This reuses the same slug format enforced on project creation and rename,
105	 * ensuring only lowercase alphanumeric characters and hyphens are accepted —
106	 * eliminating path separators and traversal sequences by design.
107	 *
108	 * @param slug - The raw slug string extracted from the request URL.
109	 */
110	function assertSafeSlug(slug: string): void {
111	  if (!assertSafeSegment(slug)) {
