121	 * blocking `..`, `.`, and all path separators by design.
122	 *
123	 * @param wpId - The raw work-package ID string extracted from the request URL.
124	 */
125	function assertSafeWpId(wpId: string): void {
126	  if (!wpId || !SAFE_ID_PATTERN.test(wpId)) {
