182	    // Intentionally downgrade AMBIGUOUS to NOT_FOUND: the caller must not learn
183	    // that multiple repos contain this slug (prevents cross-namespace existence leak).
184	    if (msg.startsWith('NOT_FOUND') || msg.startsWith('AMBIGUOUS')) {
185	      notFound(`Project '${slug}' not found.`);
186	    }
187	    throw err;
188	  }
189	
190	  try {
191	    const raw = await readFile(join(storageDir, '.meta.json'), 'utf-8');
192	    const meta = ProjectMetaSchema.parse(JSON.parse(raw));
193	    return new LedgerStore(meta.plan_path, ledgerRoot);
194	  } catch (err) {
195	    const errMsg = err instanceof Error ? err.message : String(err);
196	    process.stderr.write(
197	      `[resolveProjectStore] Failed to read metadata for slug="${slug}"` +
198	        (repoName !== undefined ? ` repo="${repoName}"` : '') +
199	        `: ${errMsg}\n`
200	    );
201	    notFound(`Project '${slug}' not found or has no metadata.`);
202	  }
203	}
